using System;
using System.IO;
using System.Linq;
using System.Runtime.Serialization.Json;
using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Xml.Serialization;

namespace MaohaiziPet {
public static class BehaviorUpgradeTests {
    static LivingReport report;
    static void Assert(bool ok,string text){if(!ok)throw new Exception(text);}
    static void Check(string name,Action run){var r=new TestResult{name=name};try{run();r.passed=true;report.passed++;}catch(Exception e){r.error=e.ToString();report.failed++;}report.tests.Add(r);}
    static void SaveXml(string path,PetSettings s){using(var f=File.Create(path))new XmlSerializer(typeof(PetSettings)).Serialize(f,s);}
    static void Picture(string path,byte color){var bytes=Enumerable.Repeat(color,64*64*4).ToArray();for(int i=3;i<bytes.Length;i+=4)bytes[i]=255;var image=BitmapSource.Create(64,64,96,96,PixelFormats.Pbgra32,null,bytes,256);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(image));using(var f=File.Create(path))png.Save(f);}
    public static int Run(string manifest,string output){
        Directory.CreateDirectory(output);PetSettings.UsePreviewProfile(Path.Combine(output,"isolated-state"));report=new LivingReport{scope="Needs-driven behavior, bounded policy, physical target planning, window-edge geometry, data recovery, atlas lifetime and native gait interruption"};
        Check("动机会随休息活动变化，隐藏时不会产生照料欠账",delegate{var awake=new PetNeeds(new PetNeedsState());var rest=new PetNeeds(new PetNeedsState());awake.Tick(600,false,true,true,12);rest.Tick(600,true,false,true,12);Assert(rest.State.Energy>awake.State.Energy&&awake.State.Appetite>rest.State.Appetite,"动机没有连接生活状态");double a=awake.State.Appetite,b=awake.State.Affection;awake.Tick(86400,false,false,false,3);Assert(awake.State.Appetite==a&&awake.State.Affection==b,"隐藏期间惩罚需求");});
        Check("投喂抚摸和玩耍改变对应动机，不只增加计数",delegate{var n=new PetNeeds(new PetNeedsState{Appetite=80,Affection=40,Curiosity=90});n.Treat();n.Touch();n.Play();Assert(n.State.Appetite<80&&n.State.Affection>40&&n.State.Curiosity<90,"互动没有影响下一步动机");});
        Check("低精力确实优先安排休息而非随机首次走动",delegate{var h=new CatHabits(37){SleepReady=true,SitReady=true,StandReady=true,WalkLeftReady=true,Needs=new PetNeeds(new PetNeedsState{Energy=10})};h.Tick(20,PetMode.Companion,false,false);Assert(h.Current==CatHabit.CurlSleep,"疲倦没有驱动休息");});
        Check("配置可以禁用自动走动，仍允许用户主动走两步",delegate{string file=Path.Combine(output,"policy.json");File.WriteAllText(file,"{\"version\":1,\"rules\":[{\"action\":\"walk-left\",\"weight\":0}]}");var h=new CatHabits(11){WalkLeftReady=true,Policy=BehaviorPolicy.Load(file)};for(int i=0;i<1200;i++){h.Tick(.25,PetMode.Companion,false,false);Assert(h.Current!=CatHabit.WalkLeft,"禁用动作仍自动出现");}h.Interrupt();Assert(h.Start(CatHabit.WalkLeft,PetMode.Companion,false),"禁用自动动作误伤手动入口");});
        Check("配置驻留范围遵守原生进入速度，不通过慢放改变停留",delegate{string file=Path.Combine(output,"dwell.json");File.WriteAllText(file,"{\"version\":1,\"rules\":[{\"action\":\"stand\",\"weight\":1,\"minDwell\":10,\"maxDwell\":12}]}");var h=new CatHabits(4){StandReady=true,Policy=BehaviorPolicy.Load(file)};h.SetResidenceTiming(CatHabit.StandUp,5,11);h.Start(CatHabit.StandUp,PetMode.Companion,false);Assert(h.DwellSeconds>=10&&h.DwellSeconds<=12&&h.EntrySeconds==5&&h.Duration==11+h.DwellSeconds,"驻留配置改坏进入过程");});
        Check("未知动作或越界配置回退默认，不执行配置中的代码",delegate{string file=Path.Combine(output,"invalid.json");foreach(string body in new[]{"{\"version\":1,\"rules\":[{\"action\":\"shell-command\",\"weight\":1}]}","{\"version\":1,\"rules\":[{\"action\":\"sit\",\"weight\":999}]}"}){File.WriteAllText(file,body);Assert(BehaviorPolicy.Load(file).UsedFallback,"无效配置被接受");}});
        Check("目标选择只使用真实可达的步幅，并避开没有空间的方向",delegate{Assert(MovementGoals.Choose(500,650,-55,55)==CatHabit.WalkRight,"没有朝目标前进");Assert(MovementGoals.Choose(500,350,-55,null)==CatHabit.WalkLeft,"没有选择可用方向");Assert(MovementGoals.Choose(500,510,-55,55)==CatHabit.None,"已经很近仍过度迈步");Assert(MovementGoals.Choose(500,650,-55,null)==CatHabit.None,"用反方向动作假装接近目标");});
        Check("一次逗猫棒会话只主动追近一次，不连续循环同一个动作",delegate{var g=new MovementGoals();Assert(g.Toy(100,300,-55,55)==CatHabit.WalkRight&&g.ToyWalk,"玩具目标未启动");g.Finished();Assert(g.Toy(155,300,-55,55)==CatHabit.None,"连续重复完整走动");g.NewTool();Assert(g.Toy(155,300,-55,55)==CatHabit.WalkRight,"新会话无法重新引导");});
        Check("窗口边缘停靠跟随位置变化，原桌面坐标保留",delegate{var p=new WindowPerch();Point at;var w=new Rect(200,300,800,500);var work=new Rect(0,0,1920,1080);Assert(p.Attach(new IntPtr(7),w,work,new Point(400,650),220,180,200,60,out at),"有效窗口无法停靠");Point before=at;Assert(p.Follow(new Rect(260,340,800,500),work,220,180,200,60,out at),"移动窗口丢失停靠");Assert(Math.Abs(at.X-before.X-60)<.01&&Math.Abs(at.Y-before.Y-40)<.01&&p.Original==new Point(400,650),"窗口跟随或原位置错误");});
        Check("最大化窗口含隐形边框时仍可停靠，窗口消失后解除附着",delegate{var p=new WindowPerch();Point at;var work=new Rect(0,0,1920,1040);Assert(p.Attach(new IntPtr(8),new Rect(-8,-8,1936,1056),work,new Point(500,700),220,180,200,60,out at)&&at.Y>=0&&at.Y+200<work.Bottom,"最大化窗口被错误拒绝或落到任务栏");Assert(!p.Follow(Rect.Empty,work,220,180,200,60,out at)&&!p.Attached,"关闭窗口后仍附着过期目标");});
        Check("小窗口和头部空间不足的边缘不会裁掉猫咪",delegate{Point at;Assert(!WindowPerch.Place(new Rect(0,0,100,80),new Rect(0,0,1920,1080),220,180,200,60,.5,true,out at),"狭小窗口被接受");Assert(!WindowPerch.Place(new Rect(100,40,800,500),new Rect(0,0,1920,1080),220,180,200,60,.5,true,out at),"头部越界未被检测");});
        Check("存档每天只备份一次，最多保留十四份",delegate{string folder=Path.Combine(output,"backup-profile");Directory.CreateDirectory(folder);string file=Path.Combine(folder,"settings.xml");for(int i=0;i<20;i++){SaveXml(file,new PetSettings{Name="日记"+i});ProfileBackups.BeforeSave(file,DateTime.Today.AddDays(i-19));}var saved=Directory.GetFiles(Path.Combine(folder,"backups"),"settings-*.xml");Assert(saved.Length==14,"备份数量失控");ProfileBackups.BeforeSave(file,DateTime.Today);Assert(Directory.GetFiles(Path.Combine(folder,"backups"),"settings-*.xml").Length==14,"同日重复备份");});
        Check("损坏存档恢复最近有效备份，并保留损坏原件",delegate{string folder=Path.Combine(output,"recovery-profile-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);string file=Path.Combine(folder,"settings.xml");SaveXml(file,new PetSettings{Name="团团",Familiarity=42,Needs=new PetNeedsState{Energy=63}});ProfileBackups.BeforeSave(file,DateTime.Today);File.WriteAllText(file,"<broken>");PetSettings.UsePreviewProfile(folder);var recovered=PetSettings.Load();Assert(recovered.Name=="团团"&&recovered.Familiarity==42&&recovered.Needs.Energy==63,"有效记录未恢复");Assert(Directory.GetFiles(folder,"settings-unreadable-*.xml").Length==1,"损坏文件被静默覆盖");recovered.Save();Assert(PetSettings.Load().Name=="团团","恢复后不能继续存档");});
        Check("缺少新增动机字段的旧存档可以继续使用",delegate{string folder=Path.Combine(output,"legacy-profile");Directory.CreateDirectory(folder);File.WriteAllText(Path.Combine(folder,"settings.xml"),"<PetSettings><Name>旧名字</Name><Familiarity>17</Familiarity></PetSettings>");PetSettings.UsePreviewProfile(folder);var s=PetSettings.Load();Assert(s.Name=="旧名字"&&s.Familiarity==17&&s.Needs!=null&&s.Needs.Energy>0,"升级丢失旧记录");});
        Check("图集缓存按预算淘汰，重新解码后的像素仍一致",delegate{string a=Path.Combine(output,"cache-a.png"),b=Path.Combine(output,"cache-b.png");Picture(a,40);Picture(b,80);var cache=new MotionAtlasCache(64*64*4);long version;var first=cache.Get(a,64,64,out version);cache.Get(b,64,64,out version);var reloaded=cache.Get(a,64,64,out version);byte[] x=new byte[64*64*4],y=new byte[x.Length];first.CopyPixels(x,256,0);reloaded.CopyPixels(y,256,0);Assert(cache.ResidentBytes<=64*64*4&&cache.DecodeCount==3&&x.SequenceEqual(y),"缓存淘汰造成像素损坏或无边界增长");});
        PetSettings.UsePreviewProfile(Path.Combine(output,"isolated-state"));var app=new Application();var c=new PetController(app);c.Skin=PetSkin.Load(manifest);c.ConfigureMotions();c.Pet=new PetWindow(c);c.Pet.Surface.Measure(new Size(c.Pet.Width,c.Pet.Height));c.Pet.Surface.Arrange(new Rect(0,0,c.Pet.Width,c.Pet.Height));
        Check("转身途中打断回到站姿接点，不倒放迈步",delegate{var clip=c.Skin.Motions.Clips["walk-right"];var p=new MotionPlayer();p.ConfigureLibrary(c.Skin.Motions);p.StartLivingWalk(clip,clip.Seconds);p.Tick((clip.Spec.gaitEntryAt-8)/24.0);Assert(p.FrameIndex>clip.Spec.standEntryAt&&p.FrameIndex<clip.Spec.gaitEntryAt,"测试没有进入转身段");p.Cancel();double time=0;while(p.RecoveredPose==null&&time<5){p.Tick(.01);time+=.01;}Assert(p.RecoveredPose=="stand"&&p.FrameIndex==clip.Spec.standEntryAt&&time<3,"转身打断仍强制播放整段长动作");p.LandRecoveredPose(20);Assert(p.HoldingPose&&p.Clip.Spec.id=="stand","无法接回自然站姿");});
        Check("迈步途中打断只向前到站稳，跳过后面的回趴长片段",delegate{foreach(string id in new[]{"walk-left","walk-right"}){var clip=c.Skin.Motions.Clips[id];var p=new MotionPlayer();p.ConfigureLibrary(c.Skin.Motions);p.StartLivingWalk(clip,clip.Seconds);p.Tick((clip.Spec.gaitEntryAt+8)/24.0);p.Cancel();int previous=p.FrameIndex;double time=0;while(p.RecoveredPose==null&&time<8){p.Tick(.01);Assert(p.FrameIndex>=previous,"取消迈步触发倒放");previous=p.FrameIndex;time+=.01;}Assert(p.RecoveredPose=="stand"&&p.FrameIndex==clip.Spec.standExitAt&&time<7,"没有使用站稳接点");p.LandRecoveredPose(20);Assert(MotionLibrary.SamePose(p.Image,c.Skin.Motions.Clips["stand"].Frames[c.Skin.Motions.Clips["stand"].Spec.holdAt]),"落稳时换姿势");}});
        c.Pet.Close();c.Dispose();using(var file=File.Create(Path.Combine(output,"behavior-upgrade-test-report.json")))new DataContractJsonSerializer(typeof(LivingReport)).WriteObject(file,report);return report.failed==0?0:1;
    }
}
}
